interface TemperatureSelectorProps {
  defaultValue: number[];
}

export const TemperatureSelector = ({
  defaultValue,
}: TemperatureSelectorProps) => {
  const [value, setValue] = useState(defaultValue);

  return (
    <div className="grid gap-2 pt-2">
      <HoverCard openDelay={200}>
